<style>
html{scroll-behavior:smooth}
body{margin:0;overflow-x:hidden}
@font-face{
 font-family:'zoho-puvi';
 src:url('https://www.elitetechcorp.com/wp-content/uploads/useanyfont/6759zoho-puvi.woff2') format('woff2');
 font-weight:100 900;font-style:normal;font-display:swap;
}
.hb{
 --ground:#F9FAFB; --ground2:#F3F4F6; --white:#FFFFFF;
 --ink:#030712; --ink2:#364153; --ink3:#4A5565; --muted:#8A8A94;
 --line:#D4D4D8; --line2:#E4E4E7;
 --blue:#236EB4; --green:#3EA900; --green-d:#008236; --forest:#032E15;
 --mint:#B9F8CF; --amber:#FEF3C6; --rose:#FFE2E2; --sky:#DBEAFE;
 --grad:linear-gradient(90deg,#236EB4 0%,#3EA900 100%);
 --hl:linear-gradient(90deg,#3EA900 0%,#2E8C5A 48%,#236EB4 100%);
 --box:1200px; --gut:24px; --r:16px; --r-sm:6px; --r-lg:24px;
 --shadow:0 1px 2px rgba(3,7,18,.04),0 8px 24px -12px rgba(3,7,18,.12);
 --shadow-lg:0 2px 4px rgba(3,7,18,.04),0 24px 56px -24px rgba(3,7,18,.18);
 --ease:cubic-bezier(.22,.75,.26,1);
 --font:'zoho-puvi','Inter',system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;
 font-family:var(--font);color:var(--ink2);background:var(--ground);
 -webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility;

}
.hb *,.hb *::before,.hb *::after{box-sizing:border-box}
.hb h1,.hb h2,.hb h3,.hb h4,.hb p,.hb ul,.hb ol,.hb li,.hb figure,.hb blockquote{margin:0;padding:0}
.hb h1,.hb h2,.hb h3,.hb h4{font-family:var(--font);color:#000;font-weight:600;letter-spacing:normal;line-height:1.2}
.hb a{color:inherit;text-decoration:none}
.hb img{max-width:100%;display:block}
.hb li{list-style:none}
/* === WordPress/Elementor override protection === */
.hb.hb h1,.hb.hb h2,.hb.hb h3,.hb.hb h4{font-family:var(--font)!important;letter-spacing:normal!important;line-height:1.2!important;margin:0!important;padding:0!important;text-transform:none!important;word-spacing:normal!important}
.hb.hb p{margin:0!important;padding:0!important}
.hb.hb ul,.hb.hb ol,.hb.hb li{margin:0!important;padding:0!important;list-style:none!important}
.hb.hb a{text-decoration:none!important}
.hb.hb img{max-width:100%!important;height:auto}
.hb.hb *,.hb.hb *::before,.hb.hb *::after{box-sizing:border-box!important}

.hb.hb .box{max-width:var(--box)!important;margin-inline:auto!important;padding-inline:var(--gut)!important;width:100%!important}
.hb.hb .sec{position:relative!important;padding-block:clamp(72px,7.5vw,120px)!important}
.hb.hb .sec--white{background:var(--white)!important}
.hb .sec--alt{background:var(--ground2)}
.hb.hb .sec--dark{background:var(--forest)!important;color:#DFF3E7!important}
.hb.hb .sec--dark h2,.hb.hb .sec--dark h3,.hb.hb .sec--dark h4{color:#fff!important}
.hb.hb .h1{font-size:clamp(31px,3.7vw,48px)!important;line-height:1.16!important}
.hb.hb h2{font-size:clamp(25px,2.8vw,37px)!important;line-height:1.24!important;color:#000!important}
.hb.hb h3{font-size:clamp(19px,1.6vw,23px)!important}
.hb.hb .lede{font-size:16.5px!important;color:#444!important;line-height:1.68!important;margin-top:16px!important;max-width:66ch!important}
.hb .sec--dark .lede{color:#CFE9D8}

/* eyebrow / labels */
.hb.hb .eyebrow{display:inline-flex!important;align-items:center!important;gap:12px!important;margin-bottom:16px!important;flex-wrap:wrap!important}
.hb .bundle-mark{display:inline-flex;gap:5px;align-items:center}
.hb .bundle-mark img{width:20px;height:20px;flex:none;object-fit:cover;object-position:left center}
.hb .bundle-mark b{font-size:13px;font-weight:700;color:#000;margin-left:4px;letter-spacing:-.01em}
.hb .sec--dark .bundle-mark b{color:#fff}
.hb.hb .eyebrow em{font-style:normal!important;font-size:12px!important;font-weight:700!important;letter-spacing:.14em!important;text-transform:uppercase!important;color:var(--muted)!important;border-left:1px solid var(--line)!important;padding-left:12px!important}
.hb .sec--dark .eyebrow em{color:#9CCFB0;border-color:rgba(255,255,255,.2)}
.hb .kicker{display:inline-flex;align-items:center;gap:8px;font-size:12.5px;font-weight:700;border-radius:999px;padding:5px 13px}
.hb .kicker--rose{color:#B91C1C;background:#FEF2F2;border:1px solid #FECACA}
.hb .kicker--green{color:var(--green-d);background:#ECFDF3;border:1px solid var(--mint)}
.hb .kicker--sky{color:#1E5A94;background:var(--sky);border:1px solid #BBD9F7}
.hb .kicker--amber{color:#8A5A14;background:var(--amber);border:1px solid #F5DDA0}

/* highlight sweep */
.hb.hb .hl{background:var(--hl)!important;color:#fff!important;padding:0 9px 2px!important;border-radius:5px!important;display:inline-block!important;line-height:1.06!important}
.hb.js .hl{background-size:0% 100%;background-repeat:no-repeat;color:#000!important;transition:background-size 1s var(--ease) .25s,color .4s .6s}
.hb.js .hl.in{background-size:100% 100%;color:#fff!important}

/* buttons */
.hb.hb .btnrow{display:flex!important;flex-wrap:wrap!important;gap:12px!important;align-items:center!important}
.hb.hb .btn{display:inline-flex!important;align-items:center!important;justify-content:center!important;gap:9px!important;font-family:var(--font)!important;font-weight:600!important;font-size:16px!important;line-height:1!important;padding:14px 26px!important;border-radius:var(--r-sm)!important;border:1px solid transparent!important;cursor:pointer!important;transition:transform .22s var(--ease),box-shadow .22s var(--ease),background .22s;text-decoration:none!important;background-image:none!important}
.hb .btn i{transition:transform .22s var(--ease)}
.hb .btn:hover i{transform:translateX(3px)}
.hb.hb .btn--g{background:var(--grad)!important;color:#fff!important;border-color:#008236!important;box-shadow:0 8px 20px -10px rgba(35,110,180,.6)!important}
.hb .btn--g:hover{transform:translateY(-2px);box-shadow:0 14px 28px -12px rgba(35,110,180,.7)}
.hb.hb .btn--o{background:#fff!important;color:#000!important;border-color:var(--line)!important}
.hb .btn--o:hover{border-color:#9CA3AF;transform:translateY(-2px)}
.hb.hb .btn--ghost{background:transparent!important;color:#fff!important;border-color:rgba(255,255,255,.35)!important}
.hb .btn--ghost:hover{background:rgba(255,255,255,.08);transform:translateY(-2px)}

/* section header block */
.hb.hb .sec-head{max-width:760px!important}
.hb.hb .sec-head.center{margin-inline:auto!important;text-align:center!important}
.hb .sec-head.center .lede{margin-inline:auto}

/* product chip */
.hb.hb .pchip{display:inline-flex!important;align-items:center!important;gap:8px!important;padding:6px 13px 6px 6px!important;border-radius:999px!important;background:var(--white)!important;border:1px solid var(--line2)!important;font-size:13px!important;font-weight:600!important;color:var(--ink)!important;box-shadow:var(--shadow)!important}
.hb .pchip img{width:22px;height:22px;object-fit:cover;object-position:left center}

/* trust counters */
.hb .stat b{display:block;font-size:clamp(34px,4vw,46px);font-weight:700;background:var(--hl);-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;line-height:1}
.hb .sec--dark .stat b{background:linear-gradient(90deg,#7BE0A0,#BEE7FF);-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent}
.hb .stat b{white-space:nowrap}
.hb .stat b .count{background:inherit;-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent}
.hb .stat>span{display:block;font-size:13px;color:var(--ink3);margin-top:8px}
.hb .sec--dark .stat>span{color:#A7C7B4}

/* pattern hero ground */
.hb .patt{position:absolute;inset:0;overflow:hidden;background:linear-gradient(120deg,#EAF1F8 0%,#EAF6EC 100%)}
.hb .patt::before{content:"";position:absolute;inset:-20% -5%;background-image:radial-gradient(circle at 20% 30%,rgba(35,110,180,.05) 0 2px,transparent 3px),radial-gradient(circle at 70% 60%,rgba(62,169,0,.05) 0 2px,transparent 3px);background-size:60px 60px}

/* image fallbacks */
.hb .jv-media,.hb .uc-img,.hb .jf-img,.hb .pp-roi-img{background:linear-gradient(135deg,#EAF6EC 0%,#EAF1F8 100%)}
.hb .bgi{background:linear-gradient(135deg,var(--ground2),var(--ground))}
/* footer */
.hb.hb .foot{background:#03140B!important;color:#9FB9AC!important;padding-block:40px!important}
.hb.hb .foot .box{display:flex!important;flex-wrap:wrap!important;gap:20px!important;justify-content:space-between!important;align-items:center!important}
.hb .foot img{height:34px}
.hb.hb .foot a{color:#CFE9D8!important}
.hb .foot .fr{display:flex;gap:22px;flex-wrap:wrap;font-size:14px}

/* trust cards (contact section) */
.hb.hb .tc-card{display:flex!important;gap:14px!important;align-items:flex-start!important;background:#fff!important;border:1px solid var(--line2)!important;border-radius:var(--r)!important;padding:20px 22px!important;box-shadow:var(--shadow)!important;transition:transform .3s var(--ease),box-shadow .3s}
.hb .tc-card:hover{transform:translateY(-3px);box-shadow:var(--shadow-lg)}
.hb.hb .tc-ic{width:42px!important;height:42px!important;border-radius:50%!important;display:grid!important;place-items:center!important;flex:none!important;font-size:18px!important}
.hb.hb .tc-ic--green{background:#ECFDF3!important;color:var(--green-d)!important}
.hb.hb .tc-card b{display:block!important;font-size:15px!important;color:#000!important}
.hb.hb .tc-card span{font-size:13px!important;color:var(--ink3)!important;line-height:1.45!important}
/* contact */
.hb.hb .cwrap{display:grid!important;grid-template-columns:1fr 1fr!important;gap:0!important;border-radius:var(--r-lg)!important;overflow:hidden!important;box-shadow:var(--shadow-lg)!important;border:1px solid var(--line2)!important}
.hb.hb .cwrap .cinfo{background:var(--forest)!important;color:#DFF3E7!important;padding:clamp(28px,3vw,48px)!important}
.hb.hb .cwrap .cinfo h3{color:#fff!important;font-size:clamp(19px,1.6vw,23px)!important}
.hb.hb .cwrap .cform{background:#fff!important;padding:clamp(28px,3vw,48px)!important}
.hb.hb .clist{margin-top:24px!important;display:grid!important;gap:16px!important}
.hb.hb .clist li{display:grid!important;grid-template-columns:38px 1fr!important;gap:12px!important;align-items:start!important;font-size:14.5px!important;color:#CFE9D8!important;list-style:none!important;padding:0!important}
.hb.hb .clist .ci{width:38px!important;height:38px!important;border-radius:10px!important;background:rgba(255,255,255,.1)!important;display:grid!important;place-items:center!important;color:#9CCFB0!important}
.hb.hb .clist b{color:#fff!important;display:block!important;font-size:14px!important}
.hb.hb .clist a{color:#CFE9D8!important;text-decoration:underline!important}
.hb.hb .wpform{border:none!important;border-radius:var(--r)!important;background:var(--ground)!important;padding:26px!important;min-height:320px!important}
.hb .wpform .code{font-family:ui-monospace,Consolas,monospace;font-size:13.5px;color:var(--ink);background:#fff;border:1px solid var(--line);border-radius:6px;padding:8px 12px;display:inline-block}

/* FAQ */
.hb.hb .qa{border:1px solid var(--line2)!important;border-radius:var(--r)!important;background:#fff!important;overflow:hidden!important;transition:border-color .3s,box-shadow .3s}
.hb .qa+.qa{margin-top:12px}
.hb .qa.open{border-color:var(--green);box-shadow:var(--shadow)}
.hb.hb .qa button{all:unset!important;box-sizing:border-box!important;width:100%!important;display:flex!important;justify-content:space-between!important;gap:18px!important;align-items:center!important;padding:22px 24px!important;cursor:pointer!important;font-weight:600!important;font-size:17px!important;color:#000!important;line-height:1.4!important;background:transparent!important;border:none!important}
.hb .qa .pm{flex:none;width:30px;height:30px;border-radius:50%;border:1px solid var(--line);position:relative;transition:background .3s,border-color .3s}
.hb .qa .pm::before,.hb .qa .pm::after{content:"";position:absolute;left:50%;top:50%;width:11px;height:2px;background:var(--ink);transform:translate(-50%,-50%);transition:transform .35s var(--ease),background .3s}
.hb .qa .pm::after{transform:translate(-50%,-50%) rotate(90deg)}
.hb .qa.open .pm{background:var(--green);border-color:var(--green)}
.hb .qa.open .pm::before,.hb .qa.open .pm::after{background:#fff}
.hb .qa.open .pm::after{transform:translate(-50%,-50%) rotate(0)}
.hb .qa .ans{display:grid;grid-template-rows:0fr;transition:grid-template-rows .45s var(--ease)}
.hb .qa.open .ans{grid-template-rows:1fr}
.hb .qa .ans>div{overflow:hidden}
.hb.hb .qa .ans p{padding:0 24px 24px!important;color:var(--ink3)!important;font-size:15.5px!important;line-height:1.65!important}

/* testimonials: carousel */
.hb .carousel-wrap{position:relative;overflow:hidden;padding:0 60px}
.hb .tst-nav{all:unset;position:absolute;top:50%;transform:translateY(-50%);width:44px;height:44px;border-radius:50%;border:1px solid var(--line2);display:grid;place-items:center;cursor:pointer;font-size:14px;color:var(--ink);background:#fff;z-index:2;box-shadow:var(--shadow);transition:background .2s,border-color .2s}
.hb .tst-nav:hover{background:var(--ground);border-color:var(--ink3)}
.hb .tst-prev{left:-6px}.hb .tst-next{right:-6px}
.hb .tst-track{display:flex;transition:transform .45s var(--ease)}
.hb.hb .tsc{min-width:calc(100% / 3)!important;max-width:calc(100% / 3)!important;flex:none!important;padding:0 12px!important;box-sizing:border-box!important}
.hb.hb .tsc-inner{background:#fff!important;border:1px solid var(--line2)!important;border-radius:var(--r)!important;padding:28px 24px!important;box-shadow:var(--shadow)!important;display:flex!important;flex-direction:column!important;height:100%!important}
.hb .tsc__ph{width:80px;height:80px;border:1px solid var(--line2);border-radius:12px;display:grid;place-items:center;padding:8px;background:#fff;margin-bottom:16px;flex:none}
.hb .tsc__ph img{max-width:100%;max-height:64px;object-fit:contain}
.hb .tsc__stars{color:#F59E0B;font-size:15px;margin-bottom:14px;display:flex;gap:2px}
.hb .tsc__stars .fa-regular{color:var(--line2)}
.hb .tsc p{color:var(--ink2);font-size:14.5px;line-height:1.65;flex:1;margin:0 0 18px;display:-webkit-box;-webkit-line-clamp:5;-webkit-box-orient:vertical;overflow:hidden}
.hb .tsc__by{font-weight:700;font-size:14px;color:#000;padding-top:14px;border-top:1px solid var(--line2);margin-top:auto}
.hb .carousel-dots{display:flex;justify-content:center;gap:8px;margin-top:28px}
.hb .carousel-dot{all:unset;width:10px;height:10px;border-radius:50%;background:var(--line2);cursor:pointer;transition:background .3s}
.hb .carousel-dot.is-active{background:var(--blue)}

/* FAQ single column */
.hb .faqcol{max-width:840px;margin-inline:auto}

/* Overall Journey (Franchise Growth Loop) — centre-line, alternating cards */
.hb .ojourney{position:relative;margin-top:52px}
.hb .ojourney::before{content:"";position:absolute;left:50%;top:0;bottom:70px;width:3px;transform:translateX(-50%);background:linear-gradient(180deg,var(--blue),var(--green));border-radius:3px}
.hb .oj-row{position:relative;display:grid;grid-template-columns:1fr 88px 1fr;align-items:start;margin-bottom:26px}
.hb .oj-node{grid-column:2;justify-self:center;width:60px;height:60px;border-radius:50%;background:#fff;border:3px solid var(--green);display:grid;place-items:center;font-weight:800;color:var(--green-d);font-size:18px;z-index:2;box-shadow:var(--shadow)}
.hb .oj-card{background:#fff;border:1px solid var(--line2);border-radius:var(--r);padding:22px 24px;box-shadow:var(--shadow);position:relative}
.hb .oj-row:nth-child(odd) .oj-card{grid-column:1;margin-right:8px}
.hb .oj-row:nth-child(even) .oj-card{grid-column:3;margin-left:8px}
.hb .oj-card h4{font-size:18px;color:#000;margin-bottom:6px}
.hb .oj-card p{font-size:14px;color:var(--ink3);line-height:1.55}
.hb .oj-apps{display:flex;flex-wrap:wrap;gap:7px;margin-top:14px}
.hb .oj-apps .pchip{font-size:12px}.hb .oj-apps .pchip img{width:20px;height:20px}
.hb .oj-tag{position:absolute;top:16px;font-size:11px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--blue)}
.hb .oj-row:nth-child(odd) .oj-tag{right:24px}.hb .oj-row:nth-child(even) .oj-tag{left:24px}
.hb .oj-loop{text-align:center;margin-top:6px;display:flex;flex-direction:column;align-items:center;gap:14px}
.hb .oj-loop .ic{width:56px;height:56px;border-radius:50%;background:var(--forest);color:#7BE0A0;display:grid;place-items:center;font-size:22px;animation:spin 9s linear infinite}
.hb .oj-loop p{max-width:60ch;color:var(--ink3);font-size:15px;line-height:1.6}
.hb.js .oj-card,.hb.js .oj-node{opacity:0;transform:translateY(26px);transition:opacity .7s var(--ease),transform .7s var(--ease)}
.hb.js .oj-node{transform:scale(.6)}
.hb.js .oj-row.in .oj-card,.hb.js .oj-row.in .oj-node{opacity:1;transform:none}
/* variant B: cards fan in from the sides */
.hb.js .ojourney--fan .oj-row:nth-child(odd) .oj-card{transform:translateX(-40px)}
.hb.js .ojourney--fan .oj-row:nth-child(even) .oj-card{transform:translateX(40px)}
.hb.js .ojourney--fan .oj-row.in .oj-card{transform:none}
/* variant C: cards tilt up */
.hb.js .ojourney--tilt .oj-card{transform:perspective(700px) rotateX(12deg) translateY(24px);transform-origin:bottom}
.hb.js .ojourney--tilt .oj-row.in .oj-card{transform:none}
@media(max-width:760px){
 .hb .ojourney::before{left:26px}
 .hb .oj-row{grid-template-columns:52px 1fr;gap:14px}
 .hb .oj-node{grid-column:1;width:52px;height:52px}
 .hb .oj-row:nth-child(odd) .oj-card,.hb .oj-row:nth-child(even) .oj-card{grid-column:2;margin:0}
 .hb .oj-tag{position:static;display:block;margin-bottom:8px}
 .hb .carousel-wrap{padding:0 52px}
 .hb .tsc{min-width:100%;max-width:100%}
 .hb .tst-nav{width:36px;height:36px;font-size:12px}
 .hb .tst-prev{left:-6px}.hb .tst-next{right:-6px}
}

/* CTA kicker (legible on dark / gradient bands) */
.hb .cta-kick{display:inline-flex;align-items:center;gap:8px;font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:#EAFBF1;background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.3);border-radius:999px;padding:6px 14px;margin-bottom:16px}
.hb .cta-kick i{color:#9EE7B8}
.hb .cta-kick--solid{color:#fff;background:rgba(255,255,255,.18)}

/* Journey shared close */
.hb .jloop{margin-top:34px;display:flex;flex-direction:column;align-items:center;gap:12px;text-align:center}
.hb .jloop .ic{width:54px;height:54px;border-radius:50%;background:var(--forest);color:#7BE0A0;display:grid;place-items:center;font-size:21px;animation:spin 9s linear infinite}
.hb .jloop p{max-width:60ch;color:var(--ink3);font-size:15px;line-height:1.6}
.hb .oj-apps{display:flex;flex-wrap:wrap;gap:7px;margin-top:14px}
.hb .oj-apps .pchip{font-size:12px}.hb .oj-apps .pchip img{width:20px;height:20px}
.hb .oj-tag{display:inline-block;font-size:11px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--blue);margin-bottom:6px}

/* Journey A · horizontal scroll filmstrip */
.hb .jfilm{display:flex;gap:0;overflow-x:auto;padding:44px 4px 24px;scroll-snap-type:x mandatory;scrollbar-width:none;-ms-overflow-style:none}
.hb .jfilm::-webkit-scrollbar{display:none}
.hb .jf-card{scroll-snap-align:center;flex:0 0 300px;background:#fff;border:1px solid var(--line2);border-radius:var(--r);overflow:hidden;box-shadow:var(--shadow)}
.hb .jf-img{position:relative;height:150px}
.hb .jf-img img{width:100%;height:100%;object-fit:cover}
.hb .jf-n{position:absolute;left:14px;top:14px;width:34px;height:34px;border-radius:50%;background:var(--grad);color:#fff;font-weight:800;display:grid;place-items:center;font-size:15px;box-shadow:var(--shadow)}
.hb .jf-body{padding:20px 22px}
.hb .jf-body h4{font-size:18px;color:#000;margin-bottom:6px}
.hb .jf-body p{font-size:14px;color:var(--ink3);line-height:1.5}
.hb .jf-arrow{flex:0 0 46px;display:grid;place-items:center;color:var(--green);font-size:20px}
.hb .jf-hint{text-align:center;font-size:13px;color:var(--muted);margin-top:6px}

/* Journey B · vertical alternating image rows on a centre line */
.hb.hb .jvert{position:relative!important;margin-top:48px!important}
.hb.hb .jvert::before{content:""!important;position:absolute!important;left:50%!important;top:0!important;bottom:0!important;width:3px!important;transform:translateX(-50%)!important;background:linear-gradient(180deg,var(--blue),var(--green))!important;border-radius:3px!important}
.hb.hb .jv-row{position:relative!important;display:grid!important;grid-template-columns:1fr 70px 1fr!important;align-items:start!important;margin-bottom:30px!important}
.hb.hb .jv-media,.hb.hb .jv-dot,.hb.hb .jv-card{grid-row:1!important}
.hb .jv-dot{grid-row:1;grid-column:2;justify-self:center;width:52px;height:52px;border-radius:50%;background:#fff;border:3px solid var(--green);color:var(--green-d);font-weight:800;display:grid;place-items:center;z-index:2;box-shadow:var(--shadow)}
.hb .jv-media{border-radius:var(--r);overflow:hidden;box-shadow:var(--shadow);aspect-ratio:16/10}
.hb .jv-media img{width:100%;height:100%;object-fit:cover;transition:transform 1.2s var(--ease)}
.hb .jv-row:hover .jv-media img{transform:scale(1.06)}
.hb .jv-card{background:#fff;border:1px solid var(--line2);border-radius:var(--r);padding:22px 24px;box-shadow:var(--shadow)}
.hb .jv-row:nth-child(odd) .jv-media{grid-column:1;grid-row:1}.hb .jv-row:nth-child(odd) .jv-card{grid-column:3;grid-row:1}
.hb .jv-row:nth-child(even) .jv-media{grid-column:3;grid-row:1}.hb .jv-row:nth-child(even) .jv-card{grid-column:1;grid-row:1;text-align:right}
.hb .jv-row:nth-child(even) .oj-apps{justify-content:flex-end}
.hb .jv-card h4{font-size:19px;color:#000;margin-bottom:6px}
.hb .jv-card p{font-size:14px;color:var(--ink3);line-height:1.55}
.hb.hb.js .jv-media,.hb.hb.js .jv-card,.hb.hb.js .jv-dot{opacity:0!important;transition:opacity .7s var(--ease),transform .7s var(--ease)}
.hb.hb.js .jv-row:nth-child(odd) .jv-media{transform:translateX(-30px)!important}.hb.hb.js .jv-row:nth-child(odd) .jv-card{transform:translateX(30px)!important}
.hb.hb.js .jv-row:nth-child(even) .jv-media{transform:translateX(30px)!important}.hb.hb.js .jv-row:nth-child(even) .jv-card{transform:translateX(-30px)!important}
.hb.hb.js .jv-dot{transform:scale(.6)!important}
.hb.hb.js .jv-row.in .jv-media,.hb.hb.js .jv-row.in .jv-card,.hb.hb.js .jv-row.in .jv-dot{opacity:1!important;transform:none!important}

/* Journey C · bento grid of image tiles that tilt in */
.hb .jgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:48px}
.hb .jg-tile{position:relative;border-radius:var(--r);overflow:hidden;min-height:250px;display:flex;box-shadow:var(--shadow)}
.hb .jg-bg{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:transform 1.3s var(--ease)}
.hb .jg-tile:hover .jg-bg{transform:scale(1.08)}
.hb .jg-shade{position:absolute;inset:0;background:linear-gradient(180deg,rgba(3,20,11,.15),rgba(3,20,11,.86))}
.hb .jg-in{position:relative;margin-top:auto;padding:22px;color:#fff;z-index:2}
.hb .jg-n{font-size:11px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:#9EE7B8}
.hb .jg-in h4{color:#fff;font-size:19px;margin:5px 0 6px}
.hb .jg-in p{color:rgba(255,255,255,.85);font-size:13.5px;line-height:1.5}
.hb .jg-apps{display:flex;gap:7px;margin-top:12px}
.hb .jg-apps img{width:30px;height:30px;background:#fff;border-radius:8px;padding:4px;object-fit:cover;object-position:left center}
.hb.hb.js .jgrid.st>*{transform:perspective(800px) rotateX(14deg) translateY(26px)!important;transform-origin:bottom!important}
.hb.hb.js .jgrid.st.in>*{transform:none!important}
@media(max-width:860px){.hb .jgrid{grid-template-columns:1fr 1fr}}
@media(max-width:760px){
 .hb.hb .jvert::before{left:26px!important}
 .hb.hb .jv-row{grid-template-columns:52px 1fr!important;gap:14px!important}
 .hb.hb .jv-dot{grid-column:1!important}
 .hb.hb .jv-row .jv-media,.hb.hb .jv-row .jv-card{grid-column:2!important;text-align:left!important}
 .hb.hb .jv-row .oj-apps{justify-content:flex-start!important}
 .hb.hb .jv-media{margin-bottom:12px!important}
}
@media(max-width:520px){.hb .jgrid{grid-template-columns:1fr}.hb .jf-card{flex-basis:80%}}

/* Comparison A · versus rows */
.hb .vs{margin-top:44px;border:1px solid var(--line2);border-radius:var(--r-lg);overflow:hidden;background:#fff;box-shadow:var(--shadow)}
.hb .vs-head,.hb .vs-row{display:grid;grid-template-columns:1.1fr 1fr 1fr;gap:0}
.hb .vs-head span{padding:16px 22px;font-size:12px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);background:var(--ground)}
.hb .vs-h{display:flex;align-items:center;gap:9px}
.hb .vs-h--us{background:var(--forest)!important;color:#fff!important}
.hb .vs-h--us img{height:18px;background:#fff;border-radius:4px;padding:1px 4px}
.hb .vs-row{border-top:1px solid var(--line2)}
.hb .vs-topic{padding:18px 22px;font-weight:700;color:#000;font-size:15px}
.hb .vs-cell{padding:18px 22px;font-size:14.5px;display:flex;gap:10px;align-items:flex-start;line-height:1.45}
.hb .vs-cell i{margin-top:3px;flex:none}
.hb .vs-us{background:#F2FBF4;color:#0A3D22}.hb .vs-us i{color:var(--green)}
.hb .vs-them{color:var(--muted)}.hb .vs-them i{color:#B91C1C}
@media(max-width:760px){.hb .vs-head{display:none}.hb .vs-row{grid-template-columns:1fr}.hb .vs-topic{background:var(--ground)}}

/* Comparison B · scoreboard strip above the columns */
.hb .scoreboard{display:flex;justify-content:center;gap:14px;align-items:center;margin:44px 0 6px;flex-wrap:wrap}
.hb .sb{display:flex;align-items:center;gap:12px;border-radius:var(--r);padding:16px 24px;border:1px solid var(--line2);background:#fff}
.hb .sb b{font-family:var(--font);font-size:30px;font-weight:800}
.hb .sb.sb--us{background:var(--forest);border-color:var(--forest);color:#fff}
.hb .sb.sb--us b{color:#7BE0A0}
.hb .sb small{font-size:13px;color:var(--ink3)}.hb .sb--us small{color:#CFE9D8}
.hb .sb-vs{font-weight:800;color:var(--muted)}

/* CTA band (shared by design-1 landing and all product pages) */
.hb .ctaband{position:relative;overflow:hidden;border-radius:var(--r-lg);min-height:400px;display:flex;align-items:center;box-shadow:var(--shadow-lg)}
.hb .ctaband>img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.hb .ctaband::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(3,46,21,.95),rgba(3,46,21,.7) 55%,rgba(3,46,21,.28))}
.hb.hb .ctaband .in{position:relative!important;z-index:2!important;padding:clamp(30px,4vw,60px)!important;max-width:640px!important;color:#fff!important}
.hb .ctaband .in.box{max-width:var(--box)}
.hb.hb .ctaband h2{color:#fff!important}
.hb.hb .ctaband p{color:#CFE9D8!important;margin-top:14px!important;font-size:16px!important;line-height:1.6!important}

/* full-bleed CTA */
.hb.hb .cta-sec{padding:0!important;overflow:visible!important}
.hb.hb .cta-full{position:relative!important;left:50%!important;right:50%!important;margin-left:-50vw!important;margin-right:-50vw!important;width:100vw!important;max-width:100vw!important;border-radius:0!important}
.hb.hb .cta-full .box{padding-block:clamp(46px,5.5vw,82px)!important}
.hb .ctaband.cta-full .in.box{max-width:var(--box)}
.hb .ctaband.cta-full .in.box p{max-width:560px}
/* CTA content centred on every page (image-backed band uses a symmetric veil) */
.hb.hb .ctaband.cta-full{justify-content:center!important;text-align:center!important}
.hb.hb .ctaband.cta-full::after{background:linear-gradient(180deg,rgba(3,46,21,.86),rgba(3,46,21,.74))!important}
.hb.hb .ctaband.cta-full .in.box{margin-inline:auto!important;max-width:900px!important;display:flex!important;flex-direction:column!important;align-items:center!important}
.hb.hb .ctaband.cta-full .in.box p{max-width:640px!important;margin-inline:auto!important}
.hb.hb .ctaband.cta-full .btnrow,.hb.hb .ctadark .btnrow,.hb.hb .ctgrad .btnrow{justify-content:center!important}
.hb .pp-others{justify-content:center}

/* section with an animated (ken-burns) background image behind a readable veil */
@keyframes bgZoom{from{transform:scale(1.04)}to{transform:scale(1.16)}}
.hb .sec--bgimg{position:relative;isolation:isolate}
.hb .sec--bgimg>.bgi{position:absolute;inset:0;z-index:-2;overflow:hidden}
.hb .sec--bgimg>.bgi img{width:100%;height:100%;object-fit:cover;animation:bgZoom 36s ease-in-out infinite alternate}
.hb .sec--bgimg::after{content:"";position:absolute;inset:0;z-index:-1;background:linear-gradient(180deg,rgba(243,244,246,.94),rgba(240,247,241,.9))}
.hb .sec--bgimg.sec--white::after{background:linear-gradient(180deg,rgba(255,255,255,.95),rgba(248,251,249,.92))}
@media(prefers-reduced-motion:reduce){.hb .sec--bgimg>.bgi img{animation:none}}

/* marquee */
.hb .marq{overflow:hidden;-webkit-mask:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent);mask:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent)}
.hb .marq .row{display:flex;gap:44px;width:max-content;align-items:center;animation:marq 46s linear infinite}
.hb .marq:hover .row{animation-play-state:paused}
.hb .marq img{height:40px;width:auto;max-width:140px;object-fit:contain;filter:grayscale(1);opacity:.62;mix-blend-mode:multiply}
@keyframes marq{to{transform:translateX(-50%)}}

/* Zoho icon motion — gentle float across every section, hover pop */
@keyframes zfloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-5px)}}
.hb.js .appitem img,.hb.js .appb img,.hb.js .capp img,.hb.js .pchip img,.hb.js .tier-apps img,.hb.js .sp-apps img,.hb.js .lp img,.hb.js .loop-node img,.hb.js .mkr i{animation:zfloat 3.8s var(--ease) infinite;will-change:transform}
.hb.js .appitem:nth-child(2n) img,.hb.js .capp:nth-child(2n) img,.hb.js .appb:nth-child(2n) img,.hb.js .pchip:nth-child(2n) img{animation-delay:.5s}
.hb.js .appitem:nth-child(3n) img,.hb.js .capp:nth-child(3n) img,.hb.js .pchip:nth-child(3n) img{animation-delay:1s}
.hb .appitem img,.hb .appb img,.hb .capp img,.hb .pchip img,.hb .loop-node img{transition:transform .3s var(--ease)}
.hb .appitem:hover img,.hb .appb:hover img,.hb .capp:hover img,.hb .pchip:hover img{transform:scale(1.14) rotate(-4deg)}
/* label chip lift on hover (icon + label move together) */
.hb .pchip{transition:transform .3s var(--ease),border-color .3s,box-shadow .3s}
.hb .pchip:hover{transform:translateY(-3px);border-color:var(--green);box-shadow:var(--shadow)}

/* reveal-on-scroll */
.hb.hb.js .rv{opacity:0!important;transform:translateY(28px)!important;transition:opacity .8s var(--ease),transform .8s var(--ease)}
.hb.hb.js .rv--l{transform:translateX(-34px)!important}
.hb.hb.js .rv--r{transform:translateX(34px)!important}
.hb.hb.js .rv--s{transform:scale(.94)!important}
.hb.hb.js .rv.in{opacity:1!important;transform:none!important}
.hb.hb.js .st>*{opacity:0!important;transform:translateY(22px)!important;transition:opacity .6s var(--ease),transform .6s var(--ease)}
.hb.hb.js .st.in>*{opacity:1!important;transform:none!important}
.hb.hb.js .st.in>*:nth-child(2){transition-delay:.07s!important}
.hb.hb.js .st.in>*:nth-child(3){transition-delay:.14s!important}
.hb.hb.js .st.in>*:nth-child(4){transition-delay:.21s!important}
.hb.hb.js .st.in>*:nth-child(5){transition-delay:.28s!important}
.hb.hb.js .st.in>*:nth-child(6){transition-delay:.35s!important}
.hb.hb.js .st.in>*:nth-child(7){transition-delay:.42s!important}
.hb.hb.js .st.in>*:nth-child(8){transition-delay:.49s!important}
.hb.hb.js .st.in>*:nth-child(n+9){transition-delay:.56s!important}
.hb.hb.js .eyebrow{opacity:0!important;transform:translateY(-10px)!important;transition:opacity .6s var(--ease),transform .6s var(--ease)}
.hb.hb.js .eyebrow.in{opacity:1!important;transform:none!important}
.hb .count-wrap{opacity:1}

@media (max-width:900px){
 .hb.hb .cwrap{grid-template-columns:1fr!important}
}
@media (prefers-reduced-motion:reduce){
 .hb.js .rv,.hb.js .st>*,.hb.js .eyebrow{opacity:1!important;transform:none!important}
 .hb.js .hl{background-size:100% 100%!important;color:#fff!important}
 .hb .marq .row,.hb.js [class] img{animation:none!important}
 .hb.js .hero-video,.hb .loop-ring::before,.hb .hero-bg i{animation:none!important}
}

.hb .p-hero{position:relative;overflow:hidden;padding-block:clamp(52px,5vw,84px);margin-top:30px}
.hb .hero-bg{position:absolute;inset:0;z-index:0;overflow:hidden;background:#EAF1F0}
.hb .hero-bg i{position:absolute;inset:-6%;background-size:cover;background-position:center}
.hb .hero-bg i:nth-child(1){opacity:.92;animation:heroZoom 30s ease-in-out infinite alternate}
.hb .hero-bg i:nth-child(2),.hb .hero-bg i:nth-child(3){opacity:0;animation:heroKen 24s var(--ease) infinite}
.hb .hero-bg i:nth-child(3){animation-delay:12s}
@keyframes heroZoom{from{transform:scale(1.04)}to{transform:scale(1.16)}}
@keyframes heroKen{0%{opacity:0;transform:scale(1.05)}8%{opacity:.9}42%{opacity:.9;transform:scale(1.14)}50%{opacity:0}100%{opacity:0}}
.hb .hero-veil{position:absolute;inset:0;z-index:1;background:linear-gradient(115deg,rgba(249,250,251,.82) 0%,rgba(249,250,251,.6) 45%,rgba(234,246,236,.42) 100%)}
.hb .patt--soft{z-index:1;background:transparent}
.hb .patt--soft::before{opacity:.4}
.hb.hb .hero-in{position:relative!important;z-index:2!important;display:grid!important;grid-template-columns:minmax(0,1fr) minmax(0,1fr)!important;gap:clamp(34px,5vw,72px)!important;align-items:stretch!important}
.hb.hb .hero-card{background:rgba(255,255,255,.9)!important;backdrop-filter:blur(7px)!important;border:1px solid rgba(255,255,255,.7)!important;border-radius:var(--r-lg)!important;box-shadow:var(--shadow-lg)!important;padding:clamp(28px,3vw,44px)!important;display:flex!important;flex-direction:column!important;justify-content:center!important}
.hb .hero-card .lede{font-size:15.5px;line-height:1.6}
.hb .hero-video{display:flex;flex-direction:column;align-items:center;justify-content:center;border-radius:var(--r-lg);overflow:hidden;animation:heroFloat 7s var(--ease) infinite}
.hb .hv-frame{position:relative;width:100%;aspect-ratio:16/9;border-radius:var(--r-lg);overflow:hidden;box-shadow:var(--shadow-lg);border:1px solid var(--line2)}
.hb .hv-frame iframe{position:absolute;inset:0;width:100%;height:100%;border:0;display:block}
@keyframes heroFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-8px)}}
@media(max-width:920px){.hb .hero-in{grid-template-columns:1fr}.hb .hero-video{order:-1;min-height:0}.hb .hv-frame{aspect-ratio:16/9}.hb .hero-card{backdrop-filter:none;background:rgba(255,255,255,.95)}}
@media(prefers-reduced-motion:reduce){.hb .hero-bg i:nth-child(1){opacity:.9;animation:none}.hb .hero-bg i:nth-child(2),.hb .hero-bg i:nth-child(3){animation:none}.hb .hero-video{animation:none}}

.hb .roicard{background:#fff;border:1px solid var(--line2);border-radius:var(--r);padding:24px 22px;transition:transform .3s var(--ease),box-shadow .3s var(--ease)}
.hb .roicard:hover{transform:translateY(-4px);box-shadow:var(--shadow)}
.hb .roicard .ri{width:46px;height:46px;border-radius:12px;background:var(--sky);color:var(--blue);display:grid;place-items:center;font-size:19px;margin-bottom:14px}
.hb .roicard:nth-child(2) .ri{background:var(--mint);color:var(--green-d)}
.hb .roicard:nth-child(3) .ri{background:var(--amber);color:#8A5A14}
.hb .roicard:nth-child(4) .ri{background:var(--rose);color:#B91C1C}
.hb .roicard h4{font-size:17px;margin-bottom:6px}
.hb .roicard p{font-size:14px;color:var(--ink3);line-height:1.55}
.hb .ba-col{border-radius:var(--r);padding:28px 26px;border:1px solid var(--line2)}
.hb .ba-before{background:#fff}
.hb .ba-after{background:var(--forest);color:#DFF3E7;border-color:var(--forest)}
.hb .ba-col h4{font-size:18px;margin-bottom:16px;display:flex;align-items:center;gap:10px}
.hb .ba-before h4{color:#000}.hb .ba-before h4 i{color:#B91C1C}
.hb .ba-after h4{color:#fff}.hb .ba-after h4 i{color:#7BE0A0}
.hb .ba-col ul{display:grid;gap:11px}
.hb .ba-col li{font-size:14.5px;line-height:1.5;padding-left:20px;position:relative}
.hb .ba-col li::before{content:"";position:absolute;left:0;top:9px;width:7px;height:7px;border-radius:50%;background:currentColor;opacity:.4}
.hb .ba-after li::before{background:#7BE0A0;opacity:1}
@media(max-width:860px){.hb .roigrid{grid-template-columns:1fr 1fr!important}.hb .ba{grid-template-columns:1fr!important}}
@media(max-width:520px){.hb .roigrid{grid-template-columns:1fr!important}}

.hb .tier{background:#fff;border:1px solid var(--line2);border-radius:var(--r);padding:30px 26px;display:flex;flex-direction:column;position:relative;transition:transform .3s var(--ease),box-shadow .3s var(--ease)}
.hb .tier:hover{transform:translateY(-4px);box-shadow:var(--shadow-lg)}
.hb .tier--feat{border-color:var(--green);box-shadow:var(--shadow)}
.hb .tier-rib{position:absolute;top:-12px;left:26px;background:var(--grad);color:#fff;font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;padding:5px 12px;border-radius:999px}
.hb .tier h3{font-size:24px}
.hb .tier-fit{color:var(--ink3);font-size:14px;margin:8px 0 18px;min-height:60px;line-height:1.5}
.hb .tier-price{font-size:26px;font-weight:800;color:#000;display:flex;align-items:baseline;gap:8px;flex-wrap:wrap}
.hb .tier-gst{font-size:12px;font-weight:600;color:var(--muted);letter-spacing:.02em}
.hb .tier-apps{display:flex;flex-wrap:wrap;gap:6px;margin:16px 0}
.hb .tier-apps img{width:26px;height:26px;border:1px solid var(--line2);border-radius:7px;padding:3px;background:#fff;object-fit:cover;object-position:left center}
.hb .tier-list{display:grid;gap:9px;margin:6px 0 24px;flex:1}
.hb .tier-list li{display:flex;gap:9px;font-size:14px;color:var(--ink2);line-height:1.45}
.hb .tier-list i{color:var(--green);margin-top:3px}
.hb .tier .btn{width:100%}
@media(max-width:860px){.hb .tiers{grid-template-columns:1fr!important}.hb .twall{columns:1!important}.hb .tgrid{grid-template-columns:1fr!important}.hb .faqgrid{grid-template-columns:1fr!important}}

/* dashboard hero (no-video product pages) */
.hb .hero-dash{display:flex;flex-direction:column;border-radius:var(--r-lg);overflow:hidden;box-shadow:var(--shadow-lg);border:1px solid var(--line2);background:#fff;min-height:420px;animation:heroFloat 7s var(--ease) infinite}
.hb .hd-bar{background:var(--forest);color:#fff;font-size:13px;font-weight:600;padding:11px 16px;display:flex;gap:9px;align-items:center;flex:none}
.hb .hd-icon{width:22px;height:22px;object-fit:cover;object-position:left center}
.hb .hd-frame{position:relative;flex:1;min-height:0;overflow:hidden}
.hb .hd-frame>img{width:100%;height:100%;object-fit:cover}
.hb .hd-pulse{position:absolute;right:20px;bottom:20px;width:56px;height:56px;border-radius:50%;background:rgba(255,255,255,.92);display:grid;place-items:center;box-shadow:var(--shadow-lg);animation:dashPulse 2.4s var(--ease) infinite}
.hb .hd-pulse img{width:32px;height:32px;object-fit:cover;object-position:left center}
@keyframes dashPulse{0%,100%{transform:scale(1);box-shadow:0 0 0 0 rgba(62,169,0,.4)}50%{transform:scale(1.08);box-shadow:0 0 0 14px rgba(62,169,0,0)}}
@media(max-width:920px){.hb .hero-dash{order:-1;min-height:0}.hb .hd-frame{aspect-ratio:16/9}}
.hb .pp-crumb{font-size:13px;color:var(--muted);margin-bottom:12px}
.hb .pp-crumb a{color:var(--blue);font-weight:600}
.hb .pp-crumb i{margin:0 4px;font-size:11px}
.hb .pp-badge{display:inline-flex;align-items:center;gap:9px;font-size:12px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;color:var(--green-d);background:var(--tint);border:1px solid var(--mint);border-radius:999px;padding:6px 14px 6px 8px}
.hb .pp-badge img{width:22px;height:22px;object-fit:cover;object-position:left center}
.hb .pp-points{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:44px}
.hb .pp-point{background:#fff;border:1px solid var(--line2);border-radius:var(--r);padding:24px;box-shadow:var(--shadow);transition:transform .3s var(--ease)}
.hb .pp-point:hover{transform:translateY(-4px)}
.hb .pp-pn{display:inline-grid;place-items:center;width:40px;height:40px;border-radius:11px;background:var(--sky);color:var(--blue);font-weight:800;margin-bottom:12px}
.hb .pp-point p{font-size:14.5px;color:var(--ink2);line-height:1.55}
/* product journey: vertical rail */
.hb.hb .pj-rail{margin-top:44px!important;display:grid!important;gap:12px!important;position:relative!important;padding-left:56px!important}
.hb.hb .pj-rail::before{content:""!important;position:absolute!important;left:24px!important;top:8px!important;bottom:8px!important;width:2px!important;background:var(--line2)!important}
.hb.hb .pj-step{position:relative!important;background:#fff!important;border:1px solid var(--line2)!important;border-radius:var(--r)!important;padding:18px 22px!important;box-shadow:var(--shadow)!important}
.hb .pj-dot{position:absolute;left:-56px;top:16px;width:48px;height:48px;border-radius:50%;background:#fff;border:1px solid var(--line2);display:grid;place-items:center;font-weight:800;color:var(--blue)}
.hb .pj-step h4{font-size:16.5px;color:#000;margin-bottom:3px}.hb .pj-step p{font-size:14px;color:var(--ink3);line-height:1.5}
/* product journey: grid */
.hb.hb .pj-grid{display:grid!important;grid-template-columns:repeat(3,1fr)!important;gap:16px!important;margin-top:44px!important}
.hb.hb .pj-tile{background:#fff!important;border:1px solid var(--line2)!important;border-radius:var(--r)!important;padding:22px!important;box-shadow:var(--shadow)!important}
.hb .pj-n{font-family:var(--font);font-weight:800;font-size:30px;color:var(--ground2);-webkit-text-stroke:1px var(--green);line-height:1}
.hb .pj-tile h4{font-size:16px;color:#000;margin:8px 0 4px}.hb .pj-tile p{font-size:13.5px;color:var(--ink3);line-height:1.5}
/* workflow */
.hb .wf-wrap{margin-top:40px;background:#fff;border:1px solid var(--line2);border-radius:var(--r-lg);padding:clamp(22px,2.4vw,34px);box-shadow:var(--shadow)}
.hb .wf-head{display:flex;align-items:center;gap:12px;margin-bottom:18px}
.hb .wf-head img{width:32px;height:32px;object-fit:cover;object-position:left center}.hb .wf-head b{font-size:19px;color:#000}
.hb .wf{display:grid;gap:10px;max-width:860px;margin-inline:auto}
.hb .wf-node{display:flex;gap:14px;align-items:flex-start;padding:16px 20px;border-radius:var(--r-sm);background:var(--ground);border:1px solid var(--line2)}
.hb .wf-nn{flex:none;width:32px;height:32px;border-radius:9px;background:var(--grad);color:#fff;font-weight:800;display:grid;place-items:center;font-size:14px}
.hb .wf-node b,.hb .wf-q b,.hb .wf-y b{display:block;color:#000;font-size:15px}
.hb .wf-node small,.hb .wf-q small,.hb .wf-y small{font-size:13px;color:var(--muted);line-height:1.45;display:block;margin-top:2px}
.hb .wf-dec{display:grid;grid-template-columns:1fr 1fr;gap:12px;padding:14px;border-radius:var(--r-sm);background:var(--amber-soft, #FBF0DF);border:1px dashed #E7C792}
.hb .wf-q{background:#fff;border-radius:10px;padding:12px 14px}.hb .wf-q b{color:#8A5A14}
.hb .wf-y{background:#fff;border-radius:10px;padding:12px 14px;position:relative}
.hb .wf-yes{font-size:10px;font-weight:800;color:var(--green-d);letter-spacing:.08em}
.hb .wf-line{height:12px;width:2px;background:var(--line);margin:0 auto}
.hb.hb .pj-parent{margin-top:24px!important;display:flex!important;gap:14px!important;align-items:flex-start!important;background:var(--tint)!important;border:1px solid var(--mint)!important;border-radius:var(--r)!important;padding:20px 24px!important}
.hb .pj-parent i{font-size:22px;color:var(--green-d);margin-top:2px}
.hb .pj-parent p{font-size:14.5px;color:var(--ink2);line-height:1.55}.hb .pj-parent b{color:#000}
/* use cases */
.hb.hb .uc-grid{display:grid!important;grid-template-columns:repeat(3,1fr)!important;gap:20px!important;margin-top:44px!important}
.hb.hb .uc-card{background:#fff!important;border:1px solid var(--line2)!important;border-radius:var(--r)!important;overflow:hidden!important;box-shadow:var(--shadow)!important;transition:transform .4s var(--ease),box-shadow .4s}
.hb .uc-card:hover{transform:translateY(-5px);box-shadow:var(--shadow-lg)}
.hb .uc-img{height:170px;overflow:hidden}.hb .uc-img img{width:100%;height:100%;object-fit:cover;transition:transform 1.2s var(--ease)}
.hb .uc-card:hover .uc-img img{transform:scale(1.07)}
.hb .uc-tx{padding:22px 24px}.hb .uc-tx h4{font-size:17px;color:#000;margin-bottom:6px}.hb .uc-tx p{font-size:14px;color:var(--ink3);line-height:1.55}
/* product roi */
.hb .pp-roi{display:grid;grid-template-columns:1fr 1fr;gap:44px;align-items:center}
.hb .pp-roi h2{font-size:clamp(24px,2.6vw,34px);color:#000;margin-top:8px}
.hb .pp-roi-img{border-radius:var(--r-lg);overflow:hidden;box-shadow:var(--shadow-lg);aspect-ratio:4/3}
.hb .pp-roi-img img{width:100%;height:100%;object-fit:cover}
/* other apps footer strip */
.hb .pp-others{display:flex;flex-wrap:wrap;gap:8px;margin-top:28px}
.hb .pp-others a{width:46px;height:46px;border-radius:12px;background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.25);display:grid;place-items:center;transition:transform .3s var(--ease)}
.hb .pp-others a:hover{transform:translateY(-3px)}
.hb .pp-others img{width:26px;height:26px;object-fit:cover;object-position:left center}
@media(max-width:860px){.hb.hb .pp-points,.hb.hb .pj-grid,.hb.hb .uc-grid{grid-template-columns:1fr 1fr!important}.hb.hb .pp-roi{grid-template-columns:1fr!important}.hb.hb .wf-dec{grid-template-columns:1fr!important}}
@media(max-width:520px){.hb.hb .pp-points,.hb.hb .pj-grid,.hb.hb .uc-grid{grid-template-columns:1fr!important}.hb.hb .pj-rail{padding-left:0!important}.hb.hb .pj-rail::before{display:none!important}.hb.hb .pj-dot{position:static!important;margin-bottom:8px!important}}
.hb.hb .cta-kick{display:inline-flex!important;align-items:center!important;gap:8px!important;font-size:13px!important;font-weight:700!important;color:#7BE0A0!important;letter-spacing:.08em!important;text-transform:uppercase!important;margin-bottom:16px!important}

.hb.hb .ctadark{background:var(--forest)!important;border-radius:var(--r-lg)!important;padding:clamp(36px,5vw,72px)!important;text-align:center!important;color:#DFF3E7!important;position:relative!important;overflow:hidden!important}
.hb.hb .ctadark h2{color:#fff!important}
.hb.hb .ctadark p{color:#CFE9D8!important;max-width:60ch!important;margin:14px auto 0!important;font-size:16px!important;line-height:1.6!important}
/* Elementor widget container: remove interference */
.elementor-widget-html .hb{max-width:none!important;padding:0!important;margin:0!important}
.elementor-widget-html .elementor-widget-container{overflow:visible!important;padding:0!important}
.elementor-widget-html .hb .box{max-width:var(--box)!important;margin-inline:auto!important;padding-inline:var(--gut)!important;width:100%!important}
.elementor-widget-html .hb .cta-full{overflow:visible!important}
.elementor-section.elementor-section-stretched .elementor-container{max-width:none!important;padding:0!important}
/* Fix: dark CTA text visibility + missing base classes */
.hb.hb .final-sec h2,.hb.hb .final-sec h3,.hb.hb .final-sec h4{color:#fff!important}
.hb.hb .final-sec .lede{color:#CFE9D8!important}
.hb.hb .final-sec .hl{background:var(--hl)!important;color:#fff!important;padding:2px 10px 4px!important;border-radius:6px!important;display:inline-block!important;box-decoration-break:clone!important;-webkit-box-decoration-break:clone!important;box-shadow:0 6px 16px -10px rgba(35,110,180,.85)!important}
.hb.hb .intro{margin-bottom:clamp(40px,3.8vw,60px)!important}
.hb.hb .intro--mid{text-align:center!important}
.hb.hb .intro--mid .lede{margin-inline:auto!important}
.hb.hb .br-lg{display:inline!important}
.hb.hb .h2{font-size:clamp(25px,2.8vw,36px)!important;line-height:1.26!important}
/* Contact - ct-grid */
@keyframes d1Float{0%{transform:translate(0,0)}50%{transform:translate(10px,-8px)}100%{transform:translate(0,0)}}
.hb.hb .sec--contact{background:linear-gradient(135deg,#EEF6FF 0%,#F0FDF4 50%,#F5F3FF 100%)!important;position:relative!important;overflow:hidden!important}
.hb.hb .sec--contact::before{content:""!important;position:absolute!important;top:-120px!important;right:-80px!important;width:400px!important;height:400px!important;border-radius:50%!important;background:radial-gradient(closest-side,rgba(35,110,180,.08),transparent 70%)!important}
.hb.hb .sec--contact::after{content:""!important;position:absolute!important;bottom:-100px!important;left:-60px!important;width:350px!important;height:350px!important;border-radius:50%!important;background:radial-gradient(closest-side,rgba(62,169,0,.07),transparent 70%)!important}
.hb.hb .ct-grid{display:grid!important;grid-template-columns:minmax(0,1fr) minmax(0,1fr)!important;gap:clamp(28px,4vw,60px)!important;align-items:start!important;position:relative!important;z-index:1!important}
.hb.hb .ct-label{display:inline-block!important;font-size:11px!important;font-weight:700!important;letter-spacing:.1em!important;text-transform:uppercase!important;background:var(--grad)!important;-webkit-background-clip:text!important;background-clip:text!important;color:transparent!important;margin-bottom:12px!important}
.hb.hb .ct-info-list{display:grid!important;gap:14px!important;margin-top:28px!important}
.hb.hb .ct-info{display:flex!important;gap:12px!important;align-items:center!important;font-size:14px!important;color:#374151!important}
.hb.hb .ct-info i{color:var(--blue)!important;font-size:16px!important;width:20px!important;text-align:center!important;flex:none!important}
.hb.hb .ct-form-slot{background:#fff!important;border:1px solid #E5E7EB!important;border-radius:var(--r)!important;overflow:hidden!important;box-shadow:0 8px 30px rgba(35,110,180,.1)!important}
.hb.hb .ct-form-head{padding:22px 28px!important;background:var(--forest)!important;border-bottom:none!important}
.hb.hb .ct-form-head b{display:block!important;font-size:17px!important;color:#fff!important}
.hb.hb .ct-form-body{padding:26px 28px 30px!important;min-height:120px!important}
/* Final CTA */
.hb.hb .final-sec{background:var(--forest)!important;color:#DFF3E7!important;position:relative!important;overflow:hidden!important}
.hb.hb .final-sec::before{content:""!important;position:absolute!important;width:680px!important;height:680px!important;border-radius:50%!important;right:-220px!important;top:-260px!important;background:radial-gradient(closest-side,rgba(62,169,0,.28),transparent 70%)!important;animation:d1Float 14s ease-in-out infinite alternate!important}
.hb.hb .final-sec::after{content:""!important;position:absolute!important;width:560px!important;height:560px!important;border-radius:50%!important;left:-200px!important;bottom:-260px!important;background:radial-gradient(closest-side,rgba(35,110,180,.3),transparent 70%)!important;animation:d1Float 18s ease-in-out infinite alternate-reverse!important}
.hb.hb .step-cards{display:grid!important;grid-template-columns:repeat(3,1fr)!important;gap:20px!important;margin-top:40px!important}
.hb.hb .step-card{background:rgba(255,255,255,.06)!important;border:1px solid rgba(255,255,255,.14)!important;border-radius:var(--r)!important;padding:28px 24px!important;text-align:center!important;transition:transform .3s var(--ease),background .3s!important}
.hb.hb .step-card:hover{transform:translateY(-4px)!important;background:rgba(255,255,255,.1)!important}
.hb.hb .step-card .step-no{font-size:28px!important;font-weight:700!important;background:var(--grad)!important;-webkit-background-clip:text!important;background-clip:text!important;color:transparent!important;margin-bottom:8px!important}
.hb.hb .step-card h4{font-size:14px!important;font-weight:700!important;letter-spacing:.08em!important;color:#fff!important;margin-bottom:8px!important}
.hb.hb .step-card p{font-size:13px!important;color:#CFE9D8!important;line-height:1.6!important}
.hb.hb .fine{margin-top:28px!important;font-size:13px!important;color:#9CCFB0!important;text-align:center!important}
.hb.hb .fine a{color:#B9F8CF!important;text-decoration:underline!important}
@media(max-width:992px){.hb.hb .ct-grid{grid-template-columns:1fr!important}.hb.hb .step-cards{grid-template-columns:1fr!important}.hb.hb .step-card{max-width:400px!important;margin-inline:auto!important}}
</style>
</head>
<body>
<div class="hb">
<section class="p-hero" id="hero">
 <div class="hero-bg" aria-hidden="true"><i style="background-image:url('https://images.unsplash.com/photo-1556761175-5973dc0f32e7?w=800&h=600&fit=crop&auto=format&q=80')"></i><i style="background-image:url('https://images.unsplash.com/photo-1556761175-5973dc0f32e7?w=800&h=600&fit=crop&auto=format&q=80')"></i><i style="background-image:url('https://images.unsplash.com/photo-1551434678-e076c223a692?w=800&h=600&fit=crop&auto=format&q=80')"></i></div>
 <div class="hero-veil"></div><div class="patt patt--soft"></div>
 <div class="box hero-in">
 <div class="hero-card rv rv--l">
 <div class="pp-crumb"><a href="https://www.elitetechcorp.com/franchise-management-system/preschool-franchise/">Zoho for Preschool Franchise</a> <i class="fa-solid fa-angle-right"></i> Zoho Desk</div>
 <div class="eyebrow"><span class="pp-badge"><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/desk.svg" alt="">Support</span></div>
 <h1 class="h1">A Preschool Franchise Support Queue Built for the Relationship That Drives Your Revenue.</h1>
 <p class="lede">Every preschool franchisee interaction, royalty questions, marketing requests, training support, territory escalations, lands in one SLA tracked queue, with full context loaded automatically the moment a ticket is raised.</p>
 <div class="btnrow" style="margin-top:24px"><a class="btn btn--g" href="https://elitemeetings.elitetechcorp.com/#/technical-consultations" target="_blank" rel="noopener">Book a Zoho Desk Demo <i class="fa-solid fa-arrow-right"></i></a><a class="btn btn--o" href="#flow">See the flow</a></div>
 </div>
 <div class="hero-video rv rv--r"><div class="hv-frame"><iframe src="https://www.youtube-nocookie.com/embed/Sb7yNk_Sj4o?rel=0&modestbranding=1&playsinline=1" title="Zoho Desk for Preschool Franchise" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe></div></div>
 </div>
 </section><section class="sec sec--white" id="summary"><div class="box">
 <div class="sec-head rv"><div class="eyebrow"><span class="bundle-mark"><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/social.svg" alt=""><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/crm.svg" alt=""><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/books.svg" alt=""><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/desk.svg" alt=""><b>Elite Tech Corp</b></span><em>What it does</em></div><h2 class="">Zoho Desk, built for<br><span class="hl">your preschool franchise network</span></h2><p class="lede">Every preschool franchisee interaction, royalty questions, marketing requests, training support, territory escalations, lands in one SLA tracked queue, with full context loaded automatically the moment a ticket is raised.</p></div>
 <div class="pp-points st"><div class="pp-point"><span class="pp-pn">01</span><p>Routes every franchisee ticket automatically into the correct departmental queue, operations, marketing, finance, training, or IT.</p></div><div class="pp-point"><span class="pp-pn">02</span><p>Prioritizes tickets by category and severity, so a launch critical issue always outranks a routine request.</p></div><div class="pp-point"><span class="pp-pn">03</span><p>Loads territory, agreement terms, and royalty status automatically the moment a ticket is opened, no manual lookup required.</p></div><div class="pp-point"><span class="pp-pn">04</span><p>Deflects repeat questions through a searchable knowledge base built around your actual operations manual.</p></div><div class="pp-point"><span class="pp-pn">05</span><p>Tracks franchisee facing SLAs precisely, particularly where they’re written directly into your franchise agreement.</p></div><div class="pp-point"><span class="pp-pn">06</span><p>Supports a franchisee community space where partners can answer each other’s questions directly.</p></div></div>
 </div></section>
<section class="sec sec--alt" id="flow"><div class="box">
 <div class="sec-head rv"><div class="eyebrow"><span class="bundle-mark"><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/social.svg" alt=""><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/crm.svg" alt=""><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/books.svg" alt=""><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/desk.svg" alt=""><b>Elite Tech Corp</b></span><em>Quick flow · the journey</em></div><h2 class="">How Zoho Desk moves a<br><span class="hl">franchise prospect forward</span></h2><p class="lede">The full user journey, then the exact workflow with every decision point, drawn from the Zoho Suite for Preschool Franchises specification.</p></div>
 <div class="jvert st">
 <div class="jv-row oj-row"><div class="jv-media"><img referrerpolicy="no-referrer" src="https://images.unsplash.com/photo-1517245386807-bb43f82c33c4?w=800&h=600&fit=crop&auto=format&q=80" alt="" loading="lazy"></div><div class="jv-dot">1</div><div class="jv-card"><h4>Raise</h4><p>A franchisee submits a ticket through the portal, email, or the franchisee community.</p></div></div>
 <div class="jv-row oj-row"><div class="jv-media"><img referrerpolicy="no-referrer" src="https://images.unsplash.com/photo-1556761175-5973dc0f32e7?w=800&h=600&fit=crop&auto=format&q=80" alt="" loading="lazy"></div><div class="jv-dot">2</div><div class="jv-card"><h4>Auto categorization</h4><p>It’s automatically routed to the correct department: operations, marketing, finance, training, or IT.</p></div></div>
 <div class="jv-row oj-row"><div class="jv-media"><img referrerpolicy="no-referrer" src="https://images.unsplash.com/photo-1573164574572-cb89e39749b4?w=800&h=600&fit=crop&auto=format&q=80" alt="" loading="lazy"></div><div class="jv-dot">3</div><div class="jv-card"><h4>Priority assignment</h4><p>Category and severity determine urgency and queue position immediately.</p></div></div>
 <div class="jv-row oj-row"><div class="jv-media"><img referrerpolicy="no-referrer" src="https://images.unsplash.com/photo-1551434678-e076c223a692?w=800&h=600&fit=crop&auto=format&q=80" alt="" loading="lazy"></div><div class="jv-dot">4</div><div class="jv-card"><h4>Context loads</h4><p>Territory, agreement terms, and royalty status appear automatically alongside the ticket.</p></div></div>
 <div class="jv-row oj-row"><div class="jv-media"><img referrerpolicy="no-referrer" src="https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?w=800&h=600&fit=crop&auto=format&q=80" alt="" loading="lazy"></div><div class="jv-dot">5</div><div class="jv-card"><h4>Branch point</h4><p>If the knowledge base already has a relevant article, the ticket is deflected with a self serve resolution; otherwise, it proceeds to the department queue.</p></div></div>
 <div class="jv-row oj-row"><div class="jv-media"><img referrerpolicy="no-referrer" src="https://images.unsplash.com/photo-1553877522-43269d4ea984?w=800&h=600&fit=crop&auto=format&q=80" alt="" loading="lazy"></div><div class="jv-dot">6</div><div class="jv-card"><h4>Departmental handling</h4><p>The assigned team member works the ticket with full context already visible.</p></div></div>
 <div class="jv-row oj-row"><div class="jv-media"><img referrerpolicy="no-referrer" src="https://images.unsplash.com/photo-1556761175-b413da4baf72?w=800&h=600&fit=crop&auto=format&q=80" alt="" loading="lazy"></div><div class="jv-dot">7</div><div class="jv-card"><h4>Branch point</h4><p>If the ticket approaches its SLA deadline, an automatic escalation alert fires to the team lead; otherwise, standard resolution continues.</p></div></div>
 <div class="jv-row oj-row"><div class="jv-media"><img referrerpolicy="no-referrer" src="https://images.unsplash.com/photo-1557804506-669a67965ba0?w=800&h=600&fit=crop&auto=format&q=80" alt="" loading="lazy"></div><div class="jv-dot">8</div><div class="jv-card"><h4>Resolution</h4><p>The ticket is closed with resolution notes attached permanently to the franchisee’s record.</p></div></div>
 </div>
 <div class="wf-wrap rv"><div class="wf-head"><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/desk.svg" alt=""><b>Zoho Desk · franchise workflow</b></div><div class="wf"><div class="wf-node rv"><span class="wf-nn">1</span><div><b>Franchisee ticket raised</b><small>Through the portal, email, or the franchisee community.</small></div></div><div class="wf-line"></div><div class="wf-node rv"><span class="wf-nn">2</span><div><b>Routed &amp; prioritized</b><small>Correct department queue set; SLA clock starts immediately.</small></div></div><div class="wf-line"></div><div class="wf-node rv"><span class="wf-nn">3</span><div><b>Resolved within SLA</b><small>Repeat questions deflected automatically by the knowledge base.</small></div></div></div></div>
 <div class="pj-parent rv"><i class="fa-solid fa-child-reaching"></i><p><b>And for a parent enquiry?</b> Parent complaints about pickup times, uniform sizes or a missed nap are a conversation for the campus. Desk carries franchisee tickets only, the relationship that produces your royalty, not the one that produces theirs.</p></div>
</div></section><section class="sec sec--white" id="usecases"><div class="box">
 <div class="sec-head rv"><div class="eyebrow"><span class="bundle-mark"><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/social.svg" alt=""><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/crm.svg" alt=""><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/books.svg" alt=""><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/desk.svg" alt=""><b>Elite Tech Corp</b></span><em>Use cases</em></div><h2 class="">Where Zoho Desk<br><span class="hl">earns its place in preschool franchising</span></h2></div>
 <div class="uc-grid st"><article class="uc-card"><div class="uc-img"><img referrerpolicy="no-referrer" onerror="this.style.opacity='0'" src="https://images.unsplash.com/photo-1556761175-5973dc0f32e7?w=800&h=600&fit=crop&auto=format&q=80" alt="" loading="lazy"></div><div class="uc-tx"><h4>Launch support, structured</h4><p>A franchisee opening in six weeks gets a checklist linked queue for signage, training slots, and supply orders.</p></div></article><article class="uc-card"><div class="uc-img"><img referrerpolicy="no-referrer" onerror="this.style.opacity='0'" src="https://images.unsplash.com/photo-1600880292203-757bb62b4baf?w=800&h=600&fit=crop&auto=format&q=80" alt="" loading="lazy"></div><div class="uc-tx"><h4>Deflecting repeat questions at scale</h4><p>A well built knowledge base answers the same forty onboarding questions once, cutting support load significantly.</p></div></article><article class="uc-card"><div class="uc-img"><img referrerpolicy="no-referrer" onerror="this.style.opacity='0'" src="https://images.unsplash.com/photo-1608222351212-18fe0ec7b13b?w=800&h=600&fit=crop&auto=format&q=80" alt="" loading="lazy"></div><div class="uc-tx"><h4>Spotting where your system is unclear</h4><p>Fifteen tickets about the same billing question is a signal the communication needs fixing, not the franchisees.</p></div></article><article class="uc-card"><div class="uc-img"><img referrerpolicy="no-referrer" onerror="this.style.opacity='0'" src="https://images.unsplash.com/photo-1551434678-e076c223a692?w=800&h=600&fit=crop&auto=format&q=80" alt="" loading="lazy"></div><div class="uc-tx"><h4>Protecting SLA commitments</h4><p>Automatic escalation ensures a ticket approaching its deadline gets attention before it breaches, not after.</p></div></article><article class="uc-card"><div class="uc-img"><img referrerpolicy="no-referrer" onerror="this.style.opacity='0'" src="https://images.unsplash.com/photo-1557804506-669a67965ba0?w=800&h=600&fit=crop&auto=format&q=80" alt="" loading="lazy"></div><div class="uc-tx"><h4>Building a self sustaining franchisee community</h4><p>Common operational questions get answered by peers, reducing load on your own team while strengthening franchisee relationships.</p></div></article></div>
 </div></section><section class="sec sec--alt" id="comparison"><div class="box">
 <div class="sec-head center rv"><div class="eyebrow"><span class="bundle-mark"><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/social.svg" alt=""><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/crm.svg" alt=""><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/books.svg" alt=""><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/desk.svg" alt=""><b>Elite Tech Corp</b></span><em>Comparison</em></div><h2 class="">Zoho Desk with <span class="hl">Elite Tech Corp,</span><br>against the manual approach</h2></div>
 <div class="vs st">
 <div class="vs-head"><span></span><span class="vs-h vs-h--us"><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="/wp-content/uploads/preschool-franchise/icons/elite-logo.png" alt="">Elite Tech Corp setup</span><span class="vs-h vs-h--them">Manual / unstructured approach</span></div>
 <div class="vs-row"><div class="vs-topic">Queue structure</div><div class="vs-cell vs-us"><i class="fa-solid fa-check"></i>Departmental, SLA tracked</div><div class="vs-cell vs-them"><i class="fa-solid fa-xmark"></i>One inbox, manual sorting</div></div><div class="vs-row"><div class="vs-topic">Context on arrival</div><div class="vs-cell vs-us"><i class="fa-solid fa-check"></i>Automatic, full history</div><div class="vs-cell vs-them"><i class="fa-solid fa-xmark"></i>Requires manual lookup</div></div><div class="vs-row"><div class="vs-topic">Repeat questions</div><div class="vs-cell vs-us"><i class="fa-solid fa-check"></i>Deflected by knowledge base</div><div class="vs-cell vs-them"><i class="fa-solid fa-xmark"></i>Answered again, every time</div></div><div class="vs-row"><div class="vs-topic">SLA enforcement</div><div class="vs-cell vs-us"><i class="fa-solid fa-check"></i>Automatic escalation</div><div class="vs-cell vs-them"><i class="fa-solid fa-xmark"></i>Not tracked</div></div><div class="vs-row"><div class="vs-topic">Franchisee community</div><div class="vs-cell vs-us"><i class="fa-solid fa-check"></i>Dedicated peer support space</div><div class="vs-cell vs-them"><i class="fa-solid fa-xmark"></i>Informal WhatsApp groups</div></div>
 </div>
 </div></section><section class="sec sec--white" id="pricing"><div class="box">
 <div class="sec-head center rv"><h2 class="">Engagement models, <span class="hl">scoped to your preschool network</span></h2><p class="lede">Zoho Desk is included from the tier shown below. Zoho licences are billed by Zoho; our preschool franchise build is a fixed written scope.</p></div>

 <div class="tiers st" style="display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:44px">
 <div class="tier">

 <h3>Launch</h3>
 <p class="tier-fit">Emerging brands with 1 to 10 operating campuses putting the split in place early.</p>
 <div class="tier-price">&#8377; xxx <span class="tier-gst">Excluding GST</span></div>
 <div class="tier-apps"><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/crm.svg" alt="Zoho CRM" title="Zoho CRM"><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/forms.svg" alt="Zoho Forms" title="Zoho Forms"><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/campaigns.svg" alt="Zoho Campaigns" title="Zoho Campaigns"><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/salesiq.svg" alt="Zoho SalesIQ" title="Zoho SalesIQ"></div>
 <ul class="tier-list"><li><i class="fa-solid fa-check"></i>Franchise and admission pipelines in Zoho CRM</li><li><i class="fa-solid fa-check"></i>Territory map encoded with live availability logic</li><li><i class="fa-solid fa-check"></i>Franchise With Us and Find a Campus forms</li><li><i class="fa-solid fa-check"></i>Franchise nurture sequence in Zoho Campaigns</li><li><i class="fa-solid fa-check"></i>Territory first SalesIQ chat flow</li><li><i class="fa-solid fa-check"></i>Onboarding and handover training for your team</li></ul>
 <a class="btn btn--o" href="https://elitemeetings.elitetechcorp.com/#/technical-consultations" target="_blank" rel="noopener">Scope this build <i class="fa-solid fa-arrow-right"></i></a>
 </div><div class="tier tier--feat">
 <span class="tier-rib">Most brands start here</span>
 <h3>Growth</h3>
 <p class="tier-fit">Networks of 10 to 50 campuses actively selling territories every quarter.</p>
 <div class="tier-price">&#8377; xxx <span class="tier-gst">Excluding GST</span></div>
