<section class="sec sec--white" id="testimonials">
 <div class="box">
 <div class="sec-head center rv"><div class="eyebrow"><span class="bundle-mark"><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/social.svg" alt=""><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/crm.svg" alt=""><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/books.svg" alt=""><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/desk.svg" alt=""><b>Elite Tech Corp</b></span><em>Customer voices</em></div><h2 class="">Don't Take Our Word for It.<br><span class="hl">Take Theirs.</span></h2><p class="lede">Preschool franchise leaders who put their operations on Zoho with Elite Tech Corp.</p></div>
 <div class="carousel-wrap rv in" id="tstCarousel">
