.hb .pp-roi h2{font-size:clamp(24px,2.6vw,34px);color:#000;margin-top:8px}
.hb .pp-roi-img{border-radius:var(--r-lg);overflow:hidden;box-shadow:var(--shadow-lg);aspect-ratio:4/3}
.hb .pp-roi-img img{width:100%;height:100%;object-fit:cover}
/* other apps footer strip */
.hb .pp-others{display:flex;flex-wrap:wrap;gap:8px;margin-top:28px}
.hb .pp-others a{width:46px;height:46px;border-radius:12px;background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.25);display:grid;place-items:center;transition:transform .3s var(--ease)}
.hb .pp-others a:hover{transform:translateY(-3px)}
.hb .pp-others img{width:26px;height:26px;object-fit:cover;object-position:left center}
@media(max-width:860px){.hb.hb .pp-points,.hb.hb .pj-grid,.hb.hb .uc-grid{grid-template-columns:1fr 1fr!important}.hb.hb .pp-roi{grid-template-columns:1fr!important}.hb.hb .wf-dec{grid-template-columns:1fr!important}}
@media(max-width:520px){.hb.hb .pp-points,.hb.hb .pj-grid,.hb.hb .uc-grid{grid-template-columns:1fr!important}.hb.hb .pj-rail{padding-left:0!important}.hb.hb .pj-rail::before{display:none!important}.hb.hb .pj-dot{position:static!important;margin-bottom:8px!important}}
.hb.hb .cta-kick{display:inline-flex!important;align-items:center!important;gap:8px!important;font-size:13px!important;font-weight:700!important;color:#7BE0A0!important;letter-spacing:.08em!important;text-transform:uppercase!important;margin-bottom:16px!important}

.hb.hb .ctadark{background:var(--forest)!important;border-radius:var(--r-lg)!important;padding:clamp(36px,5vw,72px)!important;text-align:center!important;color:#DFF3E7!important;position:relative!important;overflow:hidden!important}
.hb.hb .ctadark h2{color:#fff!important}
.hb.hb .ctadark p{color:#CFE9D8!important;max-width:60ch!important;margin:14px auto 0!important;font-size:16px!important;line-height:1.6!important}
/* Elementor widget container: remove interference */
.elementor-widget-html .hb{max-width:none!important;padding:0!important;margin:0!important}
.elementor-widget-html .elementor-widget-container{overflow:visible!important;padding:0!important}
.elementor-widget-html .hb .box{max-width:var(--box)!important;margin-inline:auto!important;padding-inline:var(--gut)!important;width:100%!important}
.elementor-widget-html .hb .cta-full{overflow:visible!important}
.elementor-section.elementor-section-stretched .elementor-container{max-width:none!important;padding:0!important}
/* Fix: dark CTA text visibility + missing base classes */
.hb.hb .final-sec h2,.hb.hb .final-sec h3,.hb.hb .final-sec h4{color:#fff!important}
.hb.hb .final-sec .lede{color:#CFE9D8!important}
.hb.hb .final-sec .hl{background:var(--hl)!important;color:#fff!important;padding:2px 10px 4px!important;border-radius:6px!important;display:inline-block!important;box-decoration-break:clone!important;-webkit-box-decoration-break:clone!important;box-shadow:0 6px 16px -10px rgba(35,110,180,.85)!important}
.hb.hb .intro{margin-bottom:clamp(40px,3.8vw,60px)!important}
.hb.hb .intro--mid{text-align:center!important}
.hb.hb .intro--mid .lede{margin-inline:auto!important}
.hb.hb .br-lg{display:inline!important}
.hb.hb .h2{font-size:clamp(25px,2.8vw,36px)!important;line-height:1.26!important}
/* Contact - ct-grid */
@keyframes d1Float{0%{transform:translate(0,0)}50%{transform:translate(10px,-8px)}100%{transform:translate(0,0)}}
.hb.hb .sec--contact{background:linear-gradient(135deg,#EEF6FF 0%,#F0FDF4 50%,#F5F3FF 100%)!important;position:relative!important;overflow:hidden!important}
.hb.hb .sec--contact::before{content:""!important;position:absolute!important;top:-120px!important;right:-80px!important;width:400px!important;height:400px!important;border-radius:50%!important;background:radial-gradient(closest-side,rgba(35,110,180,.08),transparent 70%)!important}
.hb.hb .sec--contact::after{content:""!important;position:absolute!important;bottom:-100px!important;left:-60px!important;width:350px!important;height:350px!important;border-radius:50%!important;background:radial-gradient(closest-side,rgba(62,169,0,.07),transparent 70%)!important}
.hb.hb .ct-grid{display:grid!important;grid-template-columns:minmax(0,1fr) minmax(0,1fr)!important;gap:clamp(28px,4vw,60px)!important;align-items:start!important;position:relative!important;z-index:1!important}
.hb.hb .ct-label{display:inline-block!important;font-size:11px!important;font-weight:700!important;letter-spacing:.1em!important;text-transform:uppercase!important;background:var(--grad)!important;-webkit-background-clip:text!important;background-clip:text!important;color:transparent!important;margin-bottom:12px!important}
.hb.hb .ct-info-list{display:grid!important;gap:14px!important;margin-top:28px!important}
.hb.hb .ct-info{display:flex!important;gap:12px!important;align-items:center!important;font-size:14px!important;color:#374151!important}
.hb.hb .ct-info i{color:var(--blue)!important;font-size:16px!important;width:20px!important;text-align:center!important;flex:none!important}
.hb.hb .ct-form-slot{background:#fff!important;border:1px solid #E5E7EB!important;border-radius:var(--r)!important;overflow:hidden!important;box-shadow:0 8px 30px rgba(35,110,180,.1)!important}
.hb.hb .ct-form-head{padding:22px 28px!important;background:var(--forest)!important;border-bottom:none!important}
.hb.hb .ct-form-head b{display:block!important;font-size:17px!important;color:#fff!important}
.hb.hb .ct-form-body{padding:26px 28px 30px!important;min-height:120px!important}
/* Final CTA */
.hb.hb .final-sec{background:var(--forest)!important;color:#DFF3E7!important;position:relative!important;overflow:hidden!important}
.hb.hb .final-sec::before{content:""!important;position:absolute!important;width:680px!important;height:680px!important;border-radius:50%!important;right:-220px!important;top:-260px!important;background:radial-gradient(closest-side,rgba(62,169,0,.28),transparent 70%)!important;animation:d1Float 14s ease-in-out infinite alternate!important}
.hb.hb .final-sec::after{content:""!important;position:absolute!important;width:560px!important;height:560px!important;border-radius:50%!important;left:-200px!important;bottom:-260px!important;background:radial-gradient(closest-side,rgba(35,110,180,.3),transparent 70%)!important;animation:d1Float 18s ease-in-out infinite alternate-reverse!important}
.hb.hb .step-cards{display:grid!important;grid-template-columns:repeat(3,1fr)!important;gap:20px!important;margin-top:40px!important}
.hb.hb .step-card{background:rgba(255,255,255,.06)!important;border:1px solid rgba(255,255,255,.14)!important;border-radius:var(--r)!important;padding:28px 24px!important;text-align:center!important;transition:transform .3s var(--ease),background .3s!important}
.hb.hb .step-card:hover{transform:translateY(-4px)!important;background:rgba(255,255,255,.1)!important}
.hb.hb .step-card .step-no{font-size:28px!important;font-weight:700!important;background:var(--grad)!important;-webkit-background-clip:text!important;background-clip:text!important;color:transparent!important;margin-bottom:8px!important}
.hb.hb .step-card h4{font-size:14px!important;font-weight:700!important;letter-spacing:.08em!important;color:#fff!important;margin-bottom:8px!important}
.hb.hb .step-card p{font-size:13px!important;color:#CFE9D8!important;line-height:1.6!important}
.hb.hb .fine{margin-top:28px!important;font-size:13px!important;color:#9CCFB0!important;text-align:center!important}
.hb.hb .fine a{color:#B9F8CF!important;text-decoration:underline!important}
@media(max-width:992px){.hb.hb .ct-grid{grid-template-columns:1fr!important}.hb.hb .step-cards{grid-template-columns:1fr!important}.hb.hb .step-card{max-width:400px!important;margin-inline:auto!important}}
</style>
</head>
<body>
<div class="hb">
<section class="p-hero" id="hero">
 <div class="hero-bg" aria-hidden="true"><i style="background-image:url('https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=800&h=600&fit=crop&auto=format&q=80')"></i><i style="background-image:url('https://images.unsplash.com/photo-1557804506-669a67965ba0?w=800&h=600&fit=crop&auto=format&q=80')"></i><i style="background-image:url('https://images.unsplash.com/photo-1682126196145-d23f2022a8dd?w=800&h=600&fit=crop&auto=format')"></i></div>
 <div class="hero-veil"></div><div class="patt patt--soft"></div>
 <div class="box hero-in">
 <div class="hero-card rv rv--l">
 <div class="pp-crumb"><a href="https://www.elitetechcorp.com/franchise-management-system/preschool-franchise/">Zoho for Preschool Franchise</a> <i class="fa-solid fa-angle-right"></i> Zoho Sign</div>
 <div class="eyebrow"><span class="pp-badge"><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/sign.svg" alt="">Close</span></div>
 <h1 class="h1">Close Preschool Franchise Deals in Days, Not Weeks.</h1>
 <p class="lede">Zoho Sign replaces the courier print scan cycle with sequenced digital signing, NDAs, disclosure agreements, and the preschool franchise agreement itself, approved internally before a prospect ever sees them.</p>
 <div class="btnrow" style="margin-top:24px"><a class="btn btn--g" href="https://elitemeetings.elitetechcorp.com/#/technical-consultations" target="_blank" rel="noopener">Book a Zoho Sign Demo <i class="fa-solid fa-arrow-right"></i></a><a class="btn btn--o" href="#flow">See the flow</a></div>
 </div>
 <div class="hero-dash rv rv--r"><div class="hd-bar"><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/sign.svg" alt="" class="hd-icon">Zoho Sign Dashboard</div><div class="hd-frame"><img referrerpolicy="no-referrer" onerror="this.style.opacity='0'" src="https://images.unsplash.com/photo-1450101499163-c8848c66ca85?w=800&h=600&fit=crop&auto=format&q=80" alt="Zoho Sign dashboard" loading="lazy"><div class="hd-pulse"><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/sign.svg" alt=""></div></div></div>
 </div>
 </section><section class="sec sec--white" id="summary"><div class="box">
 <div class="sec-head rv"><div class="eyebrow"><span class="bundle-mark"><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/social.svg" alt=""><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/crm.svg" alt=""><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/books.svg" alt=""><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/desk.svg" alt=""><b>Elite Tech Corp</b></span><em>What it does</em></div><h2 class="">Zoho Sign, built for<br><span class="hl">your preschool franchise network</span></h2><p class="lede">Zoho Sign replaces the courier print scan cycle with sequenced digital signing, NDAs, disclosure agreements, and the preschool franchise agreement itself, approved internally before a prospect ever sees them.</p></div>
 <div class="pp-points st"><div class="pp-point"><span class="pp-pn">01</span><p>Requires a signed NDA before any disclosure documents are released to a prospect.</p></div><div class="pp-point"><span class="pp-pn">02</span><p>Generates the franchise agreement automatically from a template with merged CRM fields, territory, term, royalty rate, launch deadline.</p></div><div class="pp-point"><span class="pp-pn">03</span><p>Enforces internal legal and management approval inside the workflow before any document reaches a prospect.</p></div><div class="pp-point"><span class="pp-pn">04</span><p>Runs multi party signing in a defined sequence, franchisee, guarantor, and your authorized signatory.</p></div><div class="pp-point"><span class="pp-pn">05</span><p>Stores every completed document with a full, timestamped audit trail.</p></div><div class="pp-point"><span class="pp-pn">06</span><p>Automatically triggers franchisee onboarding, campus creation, and royalty recording the moment signature is complete.</p></div></div>
 </div></section>
<section class="sec sec--alt" id="flow"><div class="box">
 <div class="sec-head rv"><div class="eyebrow"><span class="bundle-mark"><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/social.svg" alt=""><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/crm.svg" alt=""><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/books.svg" alt=""><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/desk.svg" alt=""><b>Elite Tech Corp</b></span><em>Quick flow · the journey</em></div><h2 class="">How Zoho Sign moves a<br><span class="hl">franchise prospect forward</span></h2><p class="lede">The full user journey, then the exact workflow with every decision point, drawn from the Zoho Suite for Preschool Franchises specification.</p></div>
 <div class="pj-grid st"><div class="pj-tile"><span class="pj-n">01</span><h4>NDA issued</h4><p>Sent automatically to a qualified prospect before any disclosure documents are shared.</p></div><div class="pj-tile"><span class="pj-n">02</span><h4>Branch point</h4><p>Once signed, disclosure documents are released immediately; if unsigned after a set period, an automatic reminder fires.</p></div><div class="pj-tile"><span class="pj-n">03</span><h4>Agreement drafted</h4><p>Generated from a template with merged fields pulling territory, term, and royalty rate directly from CRM.</p></div><div class="pj-tile"><span class="pj-n">04</span><h4>Internal review</h4><p>Legal and management approve the drafted terms inside the workflow before anything is issued externally.</p></div><div class="pj-tile"><span class="pj-n">05</span><h4>Branch point</h4><p>Approved terms proceed to signing; terms needing changes are returned internally for redrafting.</p></div><div class="pj-tile"><span class="pj-n">06</span><h4>Sequenced signing</h4><p>The franchisee, any guarantor, and your authorized signatory sign in a defined order, each seeing only what they should.</p></div><div class="pj-tile"><span class="pj-n">07</span><h4>Completion</h4><p>The signed agreement, with full audit trail, is stored against the franchisee record.</p></div><div class="pj-tile"><span class="pj-n">08</span><h4>Automatic trigger</h4><p>Completion converts the CRM lead to a franchisee record, starts the onboarding plan, creates the campus, and records royalty terms in Books.</p></div></div>
 <div class="wf-wrap rv"><div class="wf-head"><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/sign.svg" alt=""><b>Zoho Sign · franchise workflow</b></div><div class="wf"><div class="wf-node rv"><span class="wf-nn">1</span><div><b>NDA &amp; agreement drafted</b><small>Merged fields pull territory, term, and royalty rate from CRM.</small></div></div><div class="wf-line"></div><div class="wf-node rv"><span class="wf-nn">2</span><div><b>Internal approval</b><small>Legal and management sign off before anything is issued.</small></div></div><div class="wf-line"></div><div class="wf-node rv"><span class="wf-nn">3</span><div><b>Sequenced signing</b><small>Franchisee, guarantor, and your signatory sign in order.</small></div></div><div class="wf-line"></div><div class="wf-node rv"><span class="wf-nn">4</span><div><b>Signed &amp; stored</b><small>Completion automatically triggers onboarding and Books.</small></div></div></div></div>
 <div class="pj-parent rv"><i class="fa-solid fa-child-reaching"></i><p><b>And for a parent enquiry?</b> Nothing. Enrolment paperwork belongs to the campus that owns the territory. Your Sign account carries franchise agreements, territory addenda and renewals, the documents that define your business relationships, not a parent’s.</p></div>
</div></section><section class="sec sec--white" id="usecases"><div class="box">
 <div class="sec-head rv"><div class="eyebrow"><span class="bundle-mark"><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/social.svg" alt=""><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/crm.svg" alt=""><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/books.svg" alt=""><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/desk.svg" alt=""><b>Elite Tech Corp</b></span><em>Use cases</em></div><h2 class="">Where Zoho Sign<br><span class="hl">earns its place in preschool franchising</span></h2></div>
 <div class="uc-grid st"><article class="uc-card"><div class="uc-img"><img referrerpolicy="no-referrer" onerror="this.style.opacity='0'" src="https://images.unsplash.com/photo-1600880292203-757bb62b4baf?w=800&h=600&fit=crop&auto=format&q=80" alt="" loading="lazy"></div><div class="uc-tx"><h4>Cutting a month down to a week</h4><p>Sequenced digital signing removes the physical back and forth that routinely delays franchise agreements.</p></div></article><article class="uc-card"><div class="uc-img"><img referrerpolicy="no-referrer" onerror="this.style.opacity='0'" src="https://images.unsplash.com/photo-1573164574572-cb89e39749b4?w=800&h=600&fit=crop&auto=format&q=80" alt="" loading="lazy"></div><div class="uc-tx"><h4>Addenda without redrafting</h4><p>An existing franchisee adding a second territory gets a referencing addendum generated and signed in a day.</p></div></article><article class="uc-card"><div class="uc-img"><img referrerpolicy="no-referrer" onerror="this.style.opacity='0'" src="https://images.unsplash.com/photo-1600880292203-757bb62b4baf?w=800&h=600&fit=crop&auto=format&q=80" alt="" loading="lazy"></div><div class="uc-tx"><h4>Catching renewals early</h4><p>Term dates captured as data mean renewal conversations start months ahead, backed by performance data.</p></div></article><article class="uc-card"><div class="uc-img"><img referrerpolicy="no-referrer" onerror="this.style.opacity='0'" src="https://images.unsplash.com/photo-1521791055366-0d553872125f?w=800&h=600&fit=crop&auto=format" alt="" loading="lazy"></div><div class="uc-tx"><h4>Enforcing approval discipline</h4><p>No agreement reaches a prospect without documented internal sign off, protecting you from inconsistent or unauthorized terms.</p></div></article><article class="uc-card"><div class="uc-img"><img referrerpolicy="no-referrer" onerror="this.style.opacity='0'" src="https://images.unsplash.com/photo-1557804506-669a67965ba0?w=800&h=600&fit=crop&auto=format&q=80" alt="" loading="lazy"></div><div class="uc-tx"><h4>Tracking engagement before signature</h4><p>A prospect who has opened the agreement four times without signing is a very different conversation from one who hasn’t opened it at all, and that’s visible on the record.</p></div></article></div>
 </div></section><section class="sec sec--alt" id="comparison"><div class="box">
 <div class="sec-head center rv"><div class="eyebrow"><span class="bundle-mark"><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/social.svg" alt=""><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/crm.svg" alt=""><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/books.svg" alt=""><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="https://www.zohowebstatic.com/sites/zweb/images/productlogos/desk.svg" alt=""><b>Elite Tech Corp</b></span><em>Comparison</em></div><h2 class="">Zoho Sign with <span class="hl">Elite Tech Corp,</span><br>against the manual approach</h2></div>
 <div class="vs st">
 <div class="vs-head"><span></span><span class="vs-h vs-h--us"><img onerror="this.style.opacity='0'" referrerpolicy="no-referrer" src="/wp-content/uploads/preschool-franchise/icons/elite-logo.png" alt="">Elite Tech Corp setup</span><span class="vs-h vs-h--them">Manual / unstructured approach</span></div>
 <div class="vs-row"><div class="vs-topic">Agreement cycle</div><div class="vs-cell vs-us"><i class="fa-solid fa-check"></i>Days, approvals built in</div><div class="vs-cell vs-them"><i class="fa-solid fa-xmark"></i>Weeks</div></div><div class="vs-row"><div class="vs-topic">Pre issue approval</div><div class="vs-cell vs-us"><i class="fa-solid fa-check"></i>Enforced in workflow</div><div class="vs-cell vs-them"><i class="fa-solid fa-xmark"></i>Manual email chain</div></div><div class="vs-row"><div class="vs-topic">Renewal visibility</div><div class="vs-cell vs-us"><i class="fa-solid fa-check"></i>Tracked as structured data</div><div class="vs-cell vs-them"><i class="fa-solid fa-xmark"></i>Discovered late</div></div><div class="vs-row"><div class="vs-topic">Post signature automation</div><div class="vs-cell vs-us"><i class="fa-solid fa-check"></i>Onboarding and billing triggered instantly</div><div class="vs-cell vs-them"><i class="fa-solid fa-xmark"></i>Entirely manual</div></div><div class="vs-row"><div class="vs-topic">Audit trail</div><div class="vs-cell vs-us"><i class="fa-solid fa-check"></i>Timestamped, complete</div><div class="vs-cell vs-them"><i class="fa-solid fa-xmark"></i>Physical file, easily lost</div></div>
 </div>
 </div></section><section class="sec sec--white" id="pricing"><div class="box">
 <div class="sec-head center rv"><h2 class="">Engagement models, <span class="hl">scoped to your preschool network</span></h2><p class="lede">Zoho Sign is included from the tier shown below. Zoho licences are billed by Zoho; our preschool franchise build is a fixed written scope.</p></div>

 <div class="tiers st" style="display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:44px">
 <div class="tier">

 <h3>Launch</h3>
